const wireSize = {
  slug: 'wire-size-calculator',
  category: 'Wire Size & Ampacity',
  kicker: 'Wire sizing & ampacity',
  h1: 'Wire Size Calculator',
  title: 'Wire Size Calculator — What Size Wire Do I Need | Ampstowatt',
  metaDesc: 'Find the right wire size for your amps, voltage, and run length. NEC-based ampacity, the 125% continuous rule, and 3% voltage drop check in one wire gauge calculator.',
  keywords: ['wire size calculator', 'wire gauge calculator for amps', 'what size wire do i need', 'wire ampacity calculator', 'awg wire size calculator'],
  formulaPill: 'Required ampacity = Amps × 1.25 → smallest AWG that meets it',
  lead: 'Use this <strong>wire size calculator</strong> to find the smallest copper or aluminum conductor that safely carries your load. It applies the NEC 125% continuous-load rule, checks the result against 75°C ampacity (Table 310.16), and flags the run if voltage drop exceeds the recommended 3% limit.',
  reviewed: 'September 5, 2026',
  featureList: ['NEC 310.16 ampacity lookup for copper and aluminum', '125% continuous-load sizing built in', '3% voltage-drop check across your run length', 'Returns AWG plus required ampacity and drop %'],
  methodology: 'The tool multiplies your load current by 1.25 (the NEC continuous-load factor), then selects the smallest AWG whose 75°C ampacity meets or exceeds that value. It separately computes one-way voltage drop using Vdrop = 2 × length × current × resistance ÷ 1000 with per-AWG DC resistance, and warns when drop passes 3% of system voltage.',
  calc: {
    id: 'wire-size',
    title: 'Wire Size Calculator',
    subtitle: 'Smallest AWG that carries your load safely.',
    primaryLabel: 'Recommended Wire Size',
    primaryUnit: 'AWG',
    formulaText: 'Required ampacity = Amps × 1.25',
    note: 'Smallest AWG whose 75°C ampacity ≥ required, then voltage-drop checked.',
    secondary: [
      { label: 'Required Ampacity', unit: 'A' },
      { label: 'Voltage Drop', unit: '%' },
      { label: 'Voltage Drop', unit: 'V' },
    ],
    inputs: [
      { id: 'current', label: 'Load Current', unit: 'A', type: 'number', value: 50, min: 0 },
      { id: 'voltage', label: 'System Voltage', unit: 'V', type: 'select', value: '240', options: [{ v: '120', t: '120 V' }, { v: '240', t: '240 V' }, { v: '12', t: '12 V (DC)' }] },
      { id: 'length', label: 'One-Way Run Length', unit: 'ft', type: 'number', value: 50, min: 0 },
      { id: 'material', label: 'Conductor Material', unit: '', type: 'select', value: 'copper', options: [{ v: 'copper', t: 'Copper' }, { v: 'aluminum', t: 'Aluminum' }] },
    ],
    compute: function compute(v) {
      var amps = parseFloat(v.current) || 0;
      var volts = parseFloat(v.voltage) || 0;
      var len = parseFloat(v.length) || 0;
      var cu = [['14', 20, 3.14], ['12', 25, 1.98], ['10', 35, 1.24], ['8', 50, 0.778], ['6', 65, 0.491], ['4', 85, 0.308], ['3', 100, 0.245], ['2', 115, 0.194], ['1', 130, 0.154], ['1/0', 150, 0.122], ['2/0', 175, 0.0967], ['3/0', 200, 0.0766], ['4/0', 230, 0.0608]];
      var al = [['12', 20, 3.25], ['10', 30, 2.04], ['8', 40, 1.28], ['6', 50, 0.808], ['4', 65, 0.508], ['3', 75, 0.403], ['2', 90, 0.319], ['1', 100, 0.253], ['1/0', 120, 0.201], ['2/0', 135, 0.159], ['3/0', 155, 0.126], ['4/0', 180, 0.100]];
      var table = v.material === 'aluminum' ? al : cu;
      var required = amps * 1.25;
      var chosen = table[table.length - 1];
      for (var i = 0; i < table.length; i++) { if (table[i][1] >= required) { chosen = table[i]; break; } }
      var res = chosen[2];
      var vdropV = 2 * len * amps * res / 1000;
      var vdropPct = volts > 0 ? vdropV / volts * 100 : 0;
      var note = vdropPct > 3 ? chosen[0] + ' AWG carries the load, but voltage drop is ' + vdropPct.toFixed(1) + '% (over the 3% limit) — go up one size.' : chosen[0] + ' AWG meets ampacity with ' + vdropPct.toFixed(1) + '% voltage drop (within 3%).';
      return {
        primary: { label: 'Recommended Wire Size', value: chosen[0] + ' AWG', unit: '', precision: 0 },
        secondary: [
          { label: 'Required Ampacity', value: required, unit: 'A', precision: 1 },
          { label: 'Voltage Drop', value: vdropPct, unit: '%', precision: 2 },
          { label: 'Voltage Drop', value: vdropV, unit: 'V', precision: 2 },
        ],
        formula: 'Required = ' + amps + ' A × 1.25 = ' + required.toFixed(1) + ' A → ' + chosen[0] + ' AWG (' + chosen[1] + ' A)',
        note: note,
      };
    },
  },
  content: [
    { type: 'section', id: 'quick-answer', icon: '⚡', heading: 'What Size Wire Do I Need? Quick Answer', html: `<p class="content-p"><strong>To size wire, multiply your load current by 1.25 for continuous loads, then pick the smallest AWG whose ampacity meets that number.</strong> A 50-amp continuous load needs 50 × 1.25 = 62.5 A of ampacity, which at the 75°C column of <a href="/wire-gauge-calculator/">NEC Table 310.16</a> is satisfied by 6 AWG copper (65 A). Then confirm the run is not too long: voltage drop should stay under 3% for branch circuits.</p><p class="content-p">This <strong>wire size calculator</strong> handles both checks at once. It returns the recommended AWG, the required ampacity after the 125% rule, and the voltage drop across your actual one-way run length so you never undersize a conductor or overheat it. Aluminum is supported too — it carries less current per gauge, so a 50-amp aluminum feeder typically steps up to 4 AWG.</p>` },
    { type: 'section', id: 'formula', icon: 'f(x)', heading: 'The Wire Sizing Formula and the 125% Rule', html: `<p class="content-p">Two independent limits govern conductor selection: <strong>ampacity</strong> (heat) and <strong>voltage drop</strong> (performance). The wire must pass both.</p><div class="tool-guide-formula">Required ampacity = Load current × 1.25 (continuous)</div><p class="content-p">The National Electrical Code defines a <strong>continuous load</strong> as one expected to run at maximum current for three hours or more. NEC 210.20(A) and 215.3 require the overcurrent device and conductor to be rated at 125% of that continuous load — equivalently, the conductor may be loaded to only 80% of its ampacity. That is why a 65-amp wire is the correct pick for a 50-amp continuous circuit, not a 50-amp wire.</p><ul><li><strong>Ampacity</strong> — the current a conductor carries continuously without exceeding its insulation temperature rating. Read it from the 60°C, 75°C, or 90°C column of Table 310.16.</li><li><strong>The 80% / 125% rule</strong> — the same idea from two directions: size for 125% of the load, or load a wire to no more than 80% of its rating.</li><li><strong>Termination temperature</strong> — most breakers and lugs are listed for 75°C, so even with 90°C insulation you must size from the 75°C column for circuits over 100 A (and typically at or below).</li></ul><p class="content-p">For the second limit, this tool computes one-way voltage drop with Vdrop = 2 × length × current × resistance ÷ 1000, then divides by system voltage. See the dedicated <a href="/voltage-drop-calculator/">voltage drop calculator</a> for long-run design.</p>`, table: { caption: 'Copper conductor ampacity — NEC 310.16, 75°C column', columns: ['Wire Size (AWG)', 'Ampacity (75°C)', '125% Continuous Max Load', 'Typical Use'], rows: [['14', '20 A', '16 A', '15 A lighting circuits'], ['12', '25 A', '20 A', '20 A receptacles'], ['10', '35 A', '28 A', '30 A dryer/water heater'], ['8', '50 A', '40 A', '40 A range, EV charger'], ['6', '65 A', '52 A', '50 A range, hot tub'], ['4', '85 A', '68 A', '70 A subpanel feeder'], ['3', '100 A', '80 A', '100 A feeder (with derate)'], ['2', '115 A', '92 A', '100 A service (75°C)'], ['1/0', '150 A', '120 A', '150 A feeder'], ['4/0', '230 A', '184 A', '200 A service']] } },
    { type: 'section', id: 'examples', icon: '#', heading: 'Worked Examples: Sizing Wire for Real Circuits', html: `<p class="content-p"><strong>Example 1 — 50 A EV charger, 240 V, 40 ft copper:</strong> continuous load, so required = 50 × 1.25 = 62.5 A. Smallest 75°C copper conductor is 6 AWG (65 A). Voltage drop = 2 × 40 × 50 × 0.491 ÷ 1000 = 1.96 V, or 0.82% of 240 V — well under 3%. Answer: <strong>6 AWG copper</strong>.</p><p class="content-p"><strong>Example 2 — 30 A well pump, 240 V, 220 ft copper:</strong> required ampacity = 37.5 A, met by 8 AWG (50 A). But voltage drop = 2 × 220 × 30 × 0.778 ÷ 1000 = 10.3 V = 4.3% — over the limit. Step up to 6 AWG: drop = 2 × 220 × 30 × 0.491 ÷ 1000 = 6.5 V = 2.7%. On long runs, <strong>voltage drop, not ampacity, sets the size</strong>.</p><p class="content-p"><strong>Example 3 — 100 A subpanel feeder, 240 V, 60 ft copper:</strong> required = 125 A, met by 1 AWG (130 A) at 75°C. Drop = 2 × 60 × 100 × 0.154 ÷ 1000 = 1.85 V = 0.77%. Answer: <strong>1 AWG copper</strong> (many installers use 2/0 to gain margin and reuse for future upgrades). Confirm the breaker with the <a href="/breaker-size-calculator/">breaker size calculator</a>.</p><p class="content-p"><strong>Example 4 — 20 A aluminum branch, 120 V, 100 ft:</strong> required = 25 A. Aluminum 10 AWG carries 30 A. Drop = 2 × 100 × 20 × 2.04 ÷ 1000 = 8.2 V = 6.8% — too high. Aluminum's higher resistance forces an upsize to 8 AWG (drop ≈ 5.1 V, 4.3%) or a shorter run.</p>` },
    { type: 'section', id: 'derating', icon: '°', heading: 'Temperature and Bundling Derating', html: `<p class="content-p">Table 310.16 ampacities assume an ambient of 30°C (86°F) and no more than three current-carrying conductors in a raceway. Real installations often violate both, and the code requires you to <strong>derate</strong> — reduce the allowable ampacity.</p><p class="content-p"><strong>Ambient temperature correction.</strong> In a hot attic (say 50°C), a 75°C conductor's ampacity is multiplied by roughly 0.75. An 8 AWG copper wire rated 50 A becomes about 37 A of usable ampacity. This is where 90°C insulation (THHN/THWN-2) helps: you size the terminations at 75°C but apply derating from the higher 90°C ampacity, preserving margin.</p><p class="content-p"><strong>Conductor bundling.</strong> When 4–6 current-carrying conductors share a raceway, ampacity is multiplied by 0.80; for 7–9 conductors, 0.70. A conduit stuffed with circuits must use larger wire than a single-circuit run. Neutral conductors that carry only unbalanced current usually do not count, but shared neutrals on nonlinear loads may.</p><p class="content-p">Because derating stacks multiplicatively (ambient × bundling), a wire that looks adequate on the bare table can fall short in practice. When in doubt, upsize one gauge — the cost difference is small compared with a failed inspection or an overheated cable.</p>` },
    { type: 'section', id: 'voltage-drop', icon: '�­↓', heading: 'Voltage Drop: The 3% Rule Most People Miss', html: `<p class="content-p">Ampacity keeps wire from overheating; <strong>voltage drop</strong> keeps equipment working correctly. NEC 210.19 and 215.2 recommend limiting branch-circuit drop to 3% and total (feeder + branch) to 5%. These are informational notes, not hard mandates, but ignoring them causes dimming lights, motors that run hot, and electronics that misbehave.</p><div class="tool-guide-formula">Vdrop = 2 × length × current × resistance ÷ 1000</div><p class="content-p">The factor of 2 accounts for current flowing out and back on both conductors. Resistance is per 1,000 feet: about 0.491 Ω for 6 AWG copper, 0.194 Ω for 2 AWG, and roughly 1.6× those values for aluminum. Longer runs and higher currents raise drop linearly, so a circuit that is fine at 40 feet can fail at 200 feet.</p><p class="content-p">The practical takeaway: <strong>on short runs, ampacity decides the size; on long runs, voltage drop decides.</strong> This calculator reports both so you never overlook the one that governs. For a deeper treatment including 12 V DC systems, use the <a href="/voltage-drop-calculator/">voltage drop calculator</a> and the <a href="/12v-wire-size-calculator/">12V wire size calculator</a>.</p>`, table: { caption: 'Copper DC resistance and max voltage-drop-limited length (240 V, 3%, per amp)', columns: ['Wire (AWG)', 'Resistance (Ω/1000 ft)', 'Ampacity (75°C)', 'Notes'], rows: [['12', '1.98', '25 A', 'Short 20 A branches'], ['10', '1.24', '35 A', '30 A circuits'], ['8', '0.778', '50 A', '40–50 A, moderate runs'], ['6', '0.491', '65 A', '50 A, longer runs'], ['4', '0.308', '85 A', '70 A feeders'], ['2', '0.194', '115 A', '100 A, long feeders'], ['1/0', '0.122', '150 A', 'Low-drop feeders'], ['4/0', '0.0608', '230 A', '200 A service']] } },
    { type: 'section', id: 'cost-angle', icon: '$', heading: 'The Cost Angle: What Upsizing a Gauge Actually Costs', html: `<p class="content-p">Sizing conductors is not only a safety exercise — it is a budget decision, and the two pull in opposite directions. A larger gauge costs more copper per foot but wastes less energy as heat and leaves room for future load, while a minimum-legal size saves money today at the expense of margin.</p><p class="content-p">Copper price scales roughly with cross-sectional area, and each step up the AWG ladder increases area about 26%. Going from 6 AWG to 4 AWG on a 40-foot feeder might add only a modest amount to a project, yet it can cut voltage drop by a third and reclaim capacity for an EV charger or shop tools added later. On long runs the math tilts further toward upsizing: the wire that a voltage-drop check forces you to buy also runs cooler and lasts longer.</p><p class="content-p">Aluminum flips the calculation on large feeders. Even though aluminum needs one to two sizes larger, it costs far less per pound than copper, which is why 200-amp services routinely use 4/0 aluminum instead of 2/0 copper. The rule of thumb: use copper where space is tight and runs are short, and consider aluminum where the run is long, the gauge is large, and terminations are rated for it. Either way, size for the load first, then let voltage drop and future-proofing decide whether to step up.</p>` },
    { type: 'section', id: 'how-to-use', icon: '✓', heading: 'How to Use the Wire Size Calculator', html: `<ol><li><strong>Enter your load current in amps.</strong> Use the appliance nameplate rating or the branch circuit breaker size. If you only know watts, divide by voltage first, or use the <a href="/wire-gauge-calculator/">wire gauge calculator</a>.</li><li><strong>Select system voltage.</strong> 120 V for standard receptacles and lighting, 240 V for ranges, dryers, EV chargers, and subpanels, or 12 V for DC/automotive work.</li><li><strong>Enter one-way run length.</strong> Measure from the panel to the load along the actual cable path, not straight-line distance. The tool doubles it internally for the return path.</li><li><strong>Choose copper or aluminum.</strong> Copper is the default and carries more current per gauge; aluminum is common on large feeders and service entrances but needs to step up a size or two.</li></ol><p class="content-p">The recommended AWG updates instantly, along with the required ampacity and voltage drop. If the note warns that drop exceeds 3%, increase the gauge until it clears. Always verify the final choice against your local amendments and have work inspected.</p>` },
    { type: 'section', id: 'mistakes', icon: '!', heading: 'Common Wire Sizing Mistakes', html: `<ul><li><strong>Sizing to load instead of 125% of load.</strong> Continuous loads (EV chargers, electric heat, lighting) require the wire and breaker rated at 125% of the current.</li><li><strong>Using the 90°C column at terminations.</strong> Breakers and lugs are usually listed for 75°C; you may use 90°C only for derating math, not final termination sizing.</li><li><strong>Ignoring voltage drop on long runs.</strong> A 200-foot circuit can need a wire two sizes larger than ampacity alone suggests.</li><li><strong>Forgetting to derate for heat or bundling.</strong> Attics, conduit fill, and rooftop exposure all cut ampacity.</li><li><strong>Mixing aluminum and copper at terminals.</strong> Only use connectors rated CO/ALR or AL-CU, with antioxidant paste, to avoid corrosion and loose joints.</li></ul><p class="content-p">When adding a subpanel or a large appliance, pair this tool with the <a href="/breaker-size-calculator/">breaker size calculator</a> so the conductor and overcurrent device are a matched, code-compliant set.</p>` },
    { type: 'section', id: 'applications', icon: '⌂', heading: 'Applications: Homes, EVs, Solar, and Off-Grid', html: `<p class="content-p"><strong>Household circuits.</strong> 15 A lighting uses 14 AWG, 20 A receptacles use 12 AWG, 30 A dryers and water heaters use 10 AWG, and 50 A ranges use 6 AWG copper. These are the everyday defaults this calculator confirms.</p><p class="content-p"><strong>EV charging.</strong> A 48 A continuous charger (typical Level 2) requires 60 A of breaker and 6 AWG copper minimum, often 4 AWG on longer garage-to-panel runs to hold voltage drop under 3%.</p><p class="content-p"><strong>Solar and battery systems.</strong> DC circuits are voltage-drop sensitive because system voltage is low. A 30 A array at 48 V behaves very differently from the same current at 240 V — the <a href="/12v-wire-size-calculator/">12V wire size calculator</a> and <a href="/voltage-drop-calculator/">voltage drop calculator</a> are essential here.</p><p class="content-p"><strong>Subpanels and feeders.</strong> A 100 A feeder uses 1 AWG copper or 2/0 aluminum at 75°C; a 200 A service uses 4/0 copper or 250–350 kcmil aluminum. Long feeders almost always upsize for voltage drop.</p>` },
  ],
  faq: [
    { q: 'What size wire do I need for a 50 amp circuit?', a: 'For a 50-amp continuous circuit, required ampacity is 50 × 1.25 = 62.5 A, so use 6 AWG copper (65 A at 75°C) or 4 AWG aluminum. On runs longer than about 100 feet, check voltage drop and consider stepping up to 4 AWG copper.' },
    { q: 'What is the 125% rule for wire sizing?', a: 'The NEC requires conductors and breakers for continuous loads (running 3+ hours) to be rated at 125% of the load current — equivalently, loaded to no more than 80% of the wire ampacity. A 40-amp continuous load therefore needs 50 A of ampacity (8 AWG copper).' },
    { q: 'Does copper or aluminum need bigger wire?', a: 'Aluminum needs bigger wire because it has higher resistance and lower ampacity per gauge. Where 6 AWG copper carries 65 A, you need 4 AWG aluminum for the same duty. Aluminum is common on large feeders and service entrances where its lower cost and weight matter.' },
    { q: 'How does run length affect wire size?', a: 'Longer runs increase voltage drop, which can force a larger wire than ampacity alone requires. Keep branch-circuit drop under 3% and total drop under 5%. A circuit fine at 40 feet may need one or two sizes larger at 150–200 feet.' },
    { q: 'Can I use the 90°C ampacity column?', a: 'You can use 90°C ampacity for derating calculations, but final sizing must respect the termination rating — usually 75°C on breakers and lugs. So you size from the 75°C column and use the 90°C figure only to offset temperature and bundling derates.' },
    { q: 'What size wire for a 100 amp subpanel?', a: 'A 100-amp feeder needs 1 AWG copper or 2/0 aluminum at the 75°C column. Because feeders are often long, verify voltage drop; many electricians use 2/0 copper or 4/0 aluminum to keep drop low and leave room for future load.' },
    { q: 'Is this calculator NEC compliant?', a: 'It applies core NEC concepts — Table 310.16 ampacity, the 125% continuous rule, and the 3% voltage-drop recommendation — to give a sound starting size. Always adjust for temperature and bundling derating and confirm against local code and an inspection.' },
  ],
  related: [
    { href: '/wire-gauge-calculator/', badge: 'AWG', title: 'Wire Gauge Calculator', desc: 'Ampacity-based gauge lookup' },
    { href: '/voltage-drop-calculator/', badge: 'V', title: 'Voltage Drop Calculator', desc: 'Check the 3% rule on your run' },
    { href: '/breaker-size-calculator/', badge: 'A', title: 'Breaker Size Calculator', desc: 'Match overcurrent device to wire' },
    { href: '/12v-wire-size-calculator/', badge: '12V', title: '12V Wire Size Calculator', desc: 'DC voltage-drop sizing' },
    { href: '/what-size-wire-for-50-amps/', badge: '50A', title: 'Wire Size for 50 Amps', desc: 'Sizing a 50-amp circuit' },
    { href: '/conduit-fill-calculator/', badge: '%', title: 'Conduit Fill Calculator', desc: 'NEC 40% raceway fill check' },
  ],
};

