// ---------------------------------------------------------------------------
// Tool 5 — 12v-wire-size-calculator
// ---------------------------------------------------------------------------
const wire12v = {
  slug: '12v-wire-size-calculator',
  category: 'Wire Size & Ampacity',
  kicker: 'DC / low-voltage sizing',
  h1: '12V Wire Size Calculator',
  title: '12V Wire Size Calculator — DC Voltage Drop Sizing | Ampstowatt',
  metaDesc: '12V wire size calculator for marine, RV, solar, and automotive DC circuits. Sizes wire by voltage drop using circular mils (K=10.75 copper) for a target drop percentage.',
  keywords: ['12v wire size calculator', 'dc wire size calculator', '12 volt wire gauge', 'marine wire size calculator', 'rv wire size calculator'],
  formulaPill: 'CM = (2 × length × amps × 10.75) ÷ allowed volt drop',
  lead: 'This <strong>12V wire size calculator</strong> sizes DC conductors by voltage drop, not just ampacity — the right method for low-voltage marine, RV, solar, and automotive circuits. It uses the circular-mil formula (K = 10.75 for copper) to hit your target drop, then maps the result to an AWG size.',
  reviewed: 'September 5, 2026',
  featureList: ['Voltage-drop-driven DC wire sizing (ABYC style)', 'Circular-mil formula with K = 10.75 copper', 'Target drop % you choose (3% default)', 'Works for 12V and 24V systems'],
  methodology: 'The calculator computes required circular mils as (2 × one-way length × current × 10.75) ÷ allowable voltage drop in volts, maps that to the smallest AWG meeting it, then reports the actual drop for the chosen gauge. K = 10.75 is the copper constant in the standard DC marine/RV circular-mil equation.',
  calc: {
    id: 'wire-12v',
    title: '12V Wire Size Calculator',
    subtitle: 'Size DC wire by voltage drop.',
    primaryLabel: 'Recommended Wire Size',
    primaryUnit: 'AWG',
    formulaText: 'CM = (2 × length × amps × 10.75) ÷ allowed volts',
    note: 'Low-voltage DC is voltage-drop limited; K = 10.75 for copper.',
    secondary: [
      { label: 'Actual Voltage Drop', unit: '%' },
      { label: 'Voltage Drop', unit: 'V' },
      { label: 'Required Circular Mils', unit: 'CM' },
    ],
    inputs: [
      { id: 'current', label: 'Load Current', unit: 'A', type: 'number', value: 20, min: 0 },
      { id: 'length', label: 'One-Way Length', unit: 'ft', type: 'number', value: 10, min: 0 },
      { id: 'maxdrop', label: 'Max Voltage Drop', unit: '%', type: 'number', value: 3, min: 0.5, max: 20 },
      { id: 'voltage', label: 'System Voltage', unit: 'V', type: 'select', value: '12', options: [{ v: '12', t: '12 V' }, { v: '24', t: '24 V' }] },
    ],
    compute: function compute(v) {
      var amps = parseFloat(v.current) || 0;
      var len = parseFloat(v.length) || 0;
      var sysV = parseFloat(v.voltage) || 12;
      var maxPct = parseFloat(v.maxdrop) || 3;
      var allowedV = sysV * maxPct / 100;
      // [AWG, circular mils]
      var awg = [['18', 1620], ['16', 2580], ['14', 4107], ['12', 6530], ['10', 10380], ['8', 16510], ['6', 26240], ['4', 41740], ['3', 52620], ['2', 66360], ['1', 83690], ['1/0', 105600], ['2/0', 133100], ['3/0', 167800], ['4/0', 211600]];
      var reqCM = allowedV > 0 ? (2 * len * amps * 10.75) / allowedV : 0;
      var chosen = awg[awg.length - 1];
      for (var i = 0; i < awg.length; i++) { if (awg[i][1] >= reqCM) { chosen = awg[i]; break; } }
      var actualDropV = chosen[1] > 0 ? (2 * len * amps * 10.75) / chosen[1] : 0;
      var actualPct = sysV > 0 ? actualDropV / sysV * 100 : 0;
      return {
        primary: { label: 'Recommended Wire Size', value: chosen[0] + ' AWG', unit: '', precision: 0 },
        secondary: [
          { label: 'Actual Voltage Drop', value: actualPct, unit: '%', precision: 2 },
          { label: 'Voltage Drop', value: actualDropV, unit: 'V', precision: 3 },
          { label: 'Required Circular Mils', value: reqCM, unit: 'CM', precision: 0 },
        ],
        formula: 'CM = (2 × ' + len + ' × ' + amps + ' × 10.75) ÷ ' + allowedV.toFixed(2) + ' V = ' + Math.round(reqCM) + ' → ' + chosen[0] + ' AWG',
        note: chosen[0] + ' AWG gives ' + actualPct.toFixed(2) + '% actual drop (' + actualDropV.toFixed(2) + ' V) against a ' + maxPct + '% target.',
      };
    },
  },
  content: [
    { type: 'section', id: 'quick-answer', icon: '⚡', heading: '12V Wire Size: Quick Answer', html: `<p class="content-p"><strong>For 12V DC circuits, size wire by voltage drop, not ampacity.</strong> Low system voltage means even a small voltage loss is a large <em>percentage</em>, so a 0.36 V drop is already 3% on a 12 V system. Using the circular-mil formula CM = (2 × length × amps × 10.75) ÷ allowed volts, a 20 A load over 10 feet at a 3% target needs about 11,944 circular mils — which maps to <strong>8 AWG copper</strong>.</p><p class="content-p">This <strong>12V wire size calculator</strong> is built for marine, RV, solar, and automotive DC work, where the American Boat and Yacht Council (ABYC) and RV standards demand tight voltage-drop limits (3% for critical circuits, 10% for non-critical). Enter your current, one-way length, target drop, and 12 V or 24 V system voltage, and it returns the AWG plus the actual drop you will see.</p>` },
    { type: 'section', id: 'formula', icon: 'f(x)', heading: 'The Circular-Mil DC Formula (K = 10.75)', html: `<p class="content-p">DC wire sizing uses <strong>circular mils</strong> (CM) — the cross-sectional area of the conductor — because area is what determines resistance and therefore voltage drop. The standard marine/RV equation is:</p><div class="tool-guide-formula">Required CM = (2 × L × I × K) ÷ Vdrop</div><p class="content-p">Where:</p><ul><li><strong>L</strong> = one-way circuit length in feet (the 2 accounts for the round trip).</li><li><strong>I</strong> = current in amps.</li><li><strong>K</strong> = 10.75, the resistivity constant for copper in circular-mil-ohms per foot. (Aluminum uses ~17.7.)</li><li><strong>Vdrop</strong> = the allowable voltage drop in <em>volts</em> = system voltage × target percentage.</li></ul><p class="content-p">Once you have the required circular mils, you pick the smallest AWG whose area meets it. A circular mil is the area of a circle 0.001 inch in diameter; 8 AWG is 16,510 CM, 6 AWG is 26,240 CM, 4 AWG is 41,740 CM. Because each AWG step down roughly <strong>doubles</strong> the circular mils every three sizes, dropping voltage in half means going up about three gauge sizes. This is the same physics behind the general <a href="/voltage-drop-calculator/">voltage drop calculator</a>, expressed in the circular-mil form that DC/marine work prefers.</p>`, table: { caption: 'AWG to circular mils (copper conductor area)', columns: ['AWG', 'Circular Mils', 'Approx. Area', 'Typical DC Use'], rows: [['14', '4,107', 'small', 'Lighting, sensors'], ['12', '6,530', 'small', 'Cabin lights, pumps'], ['10', '10,380', 'medium', 'Fans, small inverters'], ['8', '16,510', 'medium', 'Windlass, refrigeration'], ['6', '26,240', 'large', 'Inverters, battery cables (short)'], ['4', '41,740', 'large', 'Battery banks, chargers'], ['2', '66,360', 'x-large', 'Main battery cables'], ['1/0', '105,600', 'x-large', 'High-current inverters'], ['4/0', '211,600', 'xx-large', 'Large 12V inverter feeds']] } },
    { type: 'section', id: 'examples', icon: '#', heading: 'Worked Examples: 12V DC Sizing', html: `<p class="content-p"><strong>Example 1 — 20 A, 10 ft, 3%, 12 V:</strong> allowed drop = 12 × 0.03 = 0.36 V. Required CM = (2 × 10 × 20 × 10.75) ÷ 0.36 = 4,300 ÷ 0.36 = 11,944 CM. Smallest AWG ≥ 11,944 is 8 AWG (16,510 CM). Actual drop = 4,300 ÷ 16,510 = 0.26 V = <strong>2.17%</strong>. Answer: <strong>8 AWG</strong>.</p><p class="content-p"><strong>Example 2 — 10 A LED run, 25 ft, 3%, 12 V:</strong> allowed = 0.36 V. Required CM = (2 × 25 × 10 × 10.75) ÷ 0.36 = 5,375 ÷ 0.36 = 14,931 CM → 8 AWG (16,510). Even a modest 10 A load over 25 feet needs surprisingly thick wire on 12 V — the penalty of low voltage.</p><p class="content-p"><strong>Example 3 — same load on 24 V:</strong> 10 A, 25 ft, 3%, 24 V. Allowed = 24 × 0.03 = 0.72 V. Required CM = 5,375 ÷ 0.72 = 7,465 CM → 10 AWG. <strong>Doubling system voltage roughly halves the required copper</strong> — a core reason larger DC systems move to 24 V or 48 V.</p><p class="content-p"><strong>Example 4 — 80 A windlass, 15 ft, 10%, 12 V:</strong> windlasses are non-critical, so ABYC allows 10%. Allowed = 1.2 V. Required CM = (2 × 15 × 80 × 10.75) ÷ 1.2 = 25,800 ÷ 1.2 = 21,500 CM → 6 AWG. At a 3% target it would need 4 AWG or larger — showing how the allowed-drop choice drives the gauge.</p>` },
    { type: 'section', id: 'why-dc', icon: '↓', heading: 'Why 12V Needs Thicker Wire Than 120V', html: `<p class="content-p">The same appliance wired at 12 V draws <strong>ten times the current</strong> it would at 120 V (Power = Volts × Amps). A 120 W load is 1 A at 120 V but 10 A at 12 V. Since voltage drop scales with current, low-voltage circuits lose far more voltage over the same distance — and because the <em>budget</em> (a 3% slice of 12 V is only 0.36 V) is tiny, the wire must be much larger.</p><p class="content-p">This is why:</p><ul><li>A 12 V circuit may need 8 AWG where a 120 V version uses 14 AWG for the same power.</li><li>Battery cables to inverters are often 2 AWG, 1/0, or 4/0 despite short lengths — the current is enormous.</li><li>Solar and off-grid systems migrate to 24 V and 48 V as they grow, cutting current and copper cost dramatically.</li></ul><p class="content-p">The circular-mil method captures this automatically because it works in volts of allowable drop, not a fixed ampacity. For AC circuits and the standard 3%/5% branch-feeder rules, use the <a href="/wire-size-calculator/">wire size calculator</a> instead; for pure drop analysis at any voltage, the <a href="/voltage-drop-calculator/">voltage drop calculator</a> complements this tool.</p>` },
    { type: 'section', id: 'standards', icon: '⚓', heading: 'ABYC and RV Voltage-Drop Standards', html: `<p class="content-p">Marine and RV wiring follow ABYC E-11 and RVIA guidance, which classify circuits by criticality:</p><ul><li><strong>3% maximum drop</strong> — critical circuits: navigation lights, bilge pumps, electronics, panelboard main feeds. Reliability and safety demand tight regulation.</li><li><strong>10% maximum drop</strong> — non-critical circuits: cabin lighting, general accessories, windlasses, and other intermittent loads where a little dimming is acceptable.</li></ul><p class="content-p">The calculator defaults to 3% (the conservative, critical-circuit target) but lets you enter 10% for non-critical loads to avoid over-sizing. Marine wiring adds another requirement: <strong>stranded, tinned copper</strong> for corrosion resistance and vibration tolerance — solid wire is prohibited on boats. Marine-grade wire also carries slightly different ampacity ratings, but on 12 V systems voltage drop almost always governs before ampacity does, so the circular-mil result is the binding constraint.</p><p class="content-p">Automotive DC (car audio, winches, auxiliary lighting) uses the same formula. High-current car-audio amplifiers are a classic case: a 100 A amp 15 feet from the battery needs 4 AWG or larger to avoid starving the amp under bass peaks.</p>` },
    { type: 'section', id: 'by-length', icon: '↔', heading: '12V Wire Size Chart by Length and Current (3% Target)', html: `<p class="content-p">Because voltage drop on 12 V circuits depends on both current and distance, a quick chart makes the pattern obvious before you reach for the calculator. The table below gives the smallest copper AWG that keeps a 12 V circuit under 3% drop, using the circular-mil method. Notice how the required gauge grows sharply with distance — the low-voltage penalty in action.</p><p class="content-p">Read it as a starting point, then confirm your exact numbers above. The chart also explains why van and boat builders route heavy loads (inverters, refrigeration, windlasses) as close to the battery as possible: every foot of a 12 V run costs real copper. Where a load must sit far from the battery, raising the system to 24 V or 48 V, or relocating the fuse block nearer the load, is usually cheaper than the extra cable a long 12 V run demands.</p>`, table: { caption: '12V copper wire size for 3% drop by current and one-way length', columns: ['Current', '5 ft', '10 ft', '20 ft', '30 ft'], rows: [['5 A', '14 AWG', '14 AWG', '12 AWG', '10 AWG'], ['10 A', '14 AWG', '12 AWG', '10 AWG', '8 AWG'], ['20 A', '12 AWG', '8 AWG', '6 AWG', '4 AWG'], ['30 A', '10 AWG', '8 AWG', '4 AWG', '3 AWG'], ['40 A', '8 AWG', '6 AWG', '4 AWG', '2 AWG']] } },
    { type: 'section', id: 'how-to-use', icon: '✓', heading: 'How to Use the 12V Wire Size Calculator', html: `<ol><li><strong>Enter load current in amps.</strong> For DC devices rated in watts, divide watts by system voltage (e.g., 120 W ÷ 12 V = 10 A).</li><li><strong>Enter one-way length</strong> from the source (battery or fuse block) to the load. The formula doubles it for the return path.</li><li><strong>Set your target voltage drop.</strong> Use 3% for critical circuits and battery-to-inverter cables, or up to 10% for non-critical accessory loads.</li><li><strong>Choose 12 V or 24 V.</strong> Watch the required copper shrink when you switch to 24 V — the same load needs roughly half the circular mils.</li></ol><p class="content-p">The tool returns the AWG, the actual drop percentage and volts for that gauge, and the required circular mils. If the actual drop is comfortably below your target, you have margin; if it sits right at the limit, consider the next size up for long-term reliability and future load growth.</p>` },
    { type: 'section', id: 'fusing', icon: '⏛', heading: 'Fusing, Ampacity, and Battery Cables', html: `<p class="content-p">Sizing 12V wire by voltage drop gives the conductor's minimum <em>diameter</em>, but two more checks complete a safe DC circuit: ampacity and overcurrent protection.</p><p class="content-p"><strong>Ampacity still applies.</strong> Even though voltage drop usually governs, the chosen wire must also carry the current without overheating. On short, high-current runs — battery to inverter, battery to windlass — ampacity can actually be the binding limit. A 2,000 W inverter draws roughly 165 A at 12 V; even over a 5-foot run the cable must be 2/0 or larger to handle the current and the surge, regardless of what the drop formula alone suggests.</p><p class="content-p"><strong>Fuse or breaker sizing.</strong> ABYC requires overcurrent protection within 7 inches of the battery positive terminal (or up to 72 inches if the conductor is in a protective sheath). The fuse protects the <em>wire</em>, so it must be rated at or below the conductor's ampacity — never higher. A common mistake is fitting an oversized fuse to "avoid nuisance trips," which defeats the protection and risks a cable fire. Coordinate the fuse to the wire, then verify the load draws less than the fuse rating.</p><p class="content-p"><strong>Battery cable sizing.</strong> Main battery cables are a special case: they are short but carry the full system current, so they are sized for ampacity and mechanical robustness, typically 4 AWG, 2 AWG, 1/0, or 4/0 depending on the inverter. Use fine-stranded, tinned copper with properly crimped and sealed lugs. For the AC output side of an inverter, switch to the <a href="/wire-size-calculator/">wire size calculator</a>, and confirm overcurrent devices with the <a href="/breaker-size-calculator/">breaker size calculator</a>.</p>` },
    { type: 'section', id: 'mistakes', icon: '!', heading: 'Common 12V Wiring Mistakes', html: `<ul><li><strong>Sizing by ampacity alone.</strong> On 12 V, a wire that "handles the amps" often drops far too much voltage — always size by drop.</li><li><strong>Measuring one-way but forgetting the return.</strong> The formula's factor of 2 covers both conductors; enter only the one-way length.</li><li><strong>Using solid or non-tinned wire on boats.</strong> Marine circuits require stranded, tinned copper for vibration and corrosion resistance.</li><li><strong>Undersizing battery-to-inverter cables.</strong> A 1,000 W inverter pulls ~90 A at 12 V; short runs still need 4 AWG to 1/0.</li><li><strong>Ignoring fuse placement.</strong> Fuse each conductor near the battery per ABYC; wire size and fuse rating must be coordinated.</li></ul><p class="content-p">For AC-side sizing of an inverter's output, switch to the <a href="/wire-size-calculator/">wire size calculator</a>, and confirm overcurrent protection with the <a href="/breaker-size-calculator/">breaker size calculator</a>.</p>` },
  ],
  faq: [
    { q: 'How do I calculate 12V wire size?', a: 'Use the circular-mil formula: required CM = (2 × one-way length × amps × 10.75) ÷ allowable voltage drop in volts, where allowable drop = 12 V × your target percentage. Then pick the smallest AWG whose circular mils meet that number. For 20 A over 10 feet at 3%, that is about 11,944 CM, or 8 AWG.' },
    { q: 'Why does 12V need such thick wire?', a: 'Because low voltage means high current for the same power, and the allowable voltage-drop budget is tiny — 3% of 12 V is only 0.36 V. Both effects push toward larger conductors, so a 12 V circuit often needs wire several sizes larger than a 120 V circuit of the same wattage.' },
    { q: 'What is K = 10.75 in the wire size formula?', a: 'K is the resistivity constant for copper in circular-mil-ohms per foot used in the DC voltage-drop formula; 10.75 is the standard value for copper at typical temperatures. Aluminum uses about 17.7 because it has higher resistance.' },
    { q: 'What voltage drop should I allow on a 12V circuit?', a: 'ABYC recommends 3% maximum for critical circuits (navigation, bilge pumps, electronics, main feeds) and up to 10% for non-critical loads (cabin lighting, accessories). Battery-to-inverter cables should target 3% or less.' },
    { q: 'What gauge wire for a 12V 20 amp circuit?', a: 'For 20 A over a 10-foot one-way run at 3% drop on 12 V, use 8 AWG copper. Shorter runs can use 10 AWG; longer runs need 6 AWG or larger. Always size by voltage drop for DC.' },
    { q: 'Does going to 24V reduce wire size?', a: 'Yes, significantly. Doubling system voltage halves the current for the same power and doubles the allowable drop in volts, so required circular mils drop by about half — often one to two AWG sizes smaller. This is why larger DC systems use 24 V or 48 V.' },
    { q: 'Can I use this for marine and RV wiring?', a: 'Yes — the tool uses the ABYC/RV circular-mil method. Remember marine circuits require stranded, tinned copper wire, and choose the 3% target for critical circuits or 10% for non-critical ones.' },
  ],
  related: [
    { href: '/voltage-drop-calculator/', badge: 'V', title: 'Voltage Drop Calculator', desc: 'Drop analysis at any voltage' },
    { href: '/wire-size-calculator/', badge: 'AWG', title: 'Wire Size Calculator', desc: 'AC branch and feeder sizing' },
    { href: '/wire-gauge-calculator-for-amps/', badge: 'AWG', title: 'Wire Gauge for Amps', desc: 'Ampacity-based gauge lookup' },
    { href: '/breaker-size-calculator/', badge: 'A', title: 'Breaker Size Calculator', desc: 'DC fuse and breaker sizing' },
    { href: '/wire-gauge-calculator/', badge: 'AWG', title: 'Wire Gauge Calculator', desc: 'General ampacity chart' },
    { href: '/conduit-fill-calculator/', badge: '%', title: 'Conduit Fill Calculator', desc: 'Raceway fill for DC runs' },
  ],
};

